  if (forceRefresh || stale) {
    await Promise.all([syncCanonicalProducts(), syncOrders()]);
    await setLastSyncTime('catalog');
  }

  await loadFromCache();
}, [loadFromCache]);

useFocusEffect(
  useCallback(() => {
    void refresh(false);
  }, [refresh]),
);

